function teamRequestId(){if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}
/* Central synthetic visits and role queues. Clinical records stay server-side in this module. */
navs.push('Team workspace');
let teamSession=null,teamData=null,teamWorkspaceId=localStorage.getItem('fn-team-selection')||'',teamVisitId='',teamError='',teamBusy=false,teamEditing=false;
const teamStages={physician_review:{label:'Physician review',role:'physician'},pharmacy_review:{label:'Pharmacy review',role:'pharmacist'},nursing_dose:{label:'Nursing dose documentation',role:'nurse'},complete:{label:'Demo handoff complete',role:null}};
async function teamRequest(path,method='GET',data){const suffix=path.includes('?')?'&':'?';const r=await fetch('/api/team/'+path+(teamWorkspaceId?suffix+'workspace='+encodeURIComponent(teamWorkspaceId):''),{method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let value;try{value=await r.json()}catch{throw Error('Shared backend unavailable. Check connection and use the published app.')}if(r.status===401){teamSession={signedIn:false};throw Error(value.error)}if(!r.ok)throw Error(value.error||'Server operation failed');return value}
function teamFingerprint(){return JSON.stringify([teamSession,teamData?{...teamData,serverTime:null}:null,teamError])}
async function refreshTeamWorkspace(silent=false){const before=teamFingerprint();if(teamBusy||silent&&teamEditing)return;if(teamEditing&&!silent){openDialog('Unsaved handoff draft','<p>Refreshing replaces the unsaved form with server data. Save the handoff first, or discard your draft.</p><button class="btn" onclick="closeDialog()">Keep editing</button><button class="btn" onclick="teamEditing=false;closeDialog();refreshTeamWorkspace()">Discard draft and refresh</button>');return}teamBusy=true;try{teamError='';teamSession=await teamRequest('session');if(teamWorkspaceId&&!teamSession.workspaces.some(w=>w.id===teamWorkspaceId)){teamWorkspaceId='';teamData=null}if(!teamWorkspaceId&&teamSession.workspaces.length)teamWorkspaceId=teamSession.workspaces[0].id;if(teamWorkspaceId){teamData=await teamRequest('workspace');if(!teamVisitId||!teamData.visits.some(v=>v.id===teamVisitId))teamVisitId=teamData.visits[0]?.id||'';localStorage.setItem('fn-team-selection',teamWorkspaceId)}}catch(e){teamError=e.message;if(!silent)teamData=null}finally{teamBusy=false;if(view==='Team workspace'&&(!silent||before!==teamFingerprint()))render()}}
function teamRoleCan(role){return teamData&&['admin',role].includes(teamData.membership.role)}
function teamWorkspaceView(){const signed=teamSession?.signedIn;return header('Connected demo hospital','One server visit shared by nursing, physician and pharmacy roles.',`<button class="btn" onclick="refreshTeamWorkspace()">Refresh server</button>`)+`<div class="notice"><b>Synthetic training workspace only.</b> Central records here are separate from the original device-local registry. Tasks are assigned to role queues; external messages, clinical order transmission and real emergency response remain disconnected.</div>${teamError?`<p class="notice" role="alert">${esc(teamError)}</p>`:''}${!signed?`<section class="panel"><h2>Start a connected demonstration</h2><p>Sign in, create a fictional hospital, then open the same workspace on your other device. Staff sign up independently and the Super Admin approves their assigned roles.</p><div class="actions"><button class="btn primary" onclick="fnAccount.load()">Sign in to application</button><button class="btn" onclick="refreshTeamWorkspace()">Check my sign-in</button></div><p>Already signed in? Check your sign-in to load your workspaces.</p></section>`:`<section class="panel"><div class="tools">${teamSession.workspaces.length?`<label class="field">Workspace<select aria-label="Connected workspace" onchange="chooseTeamWorkspace(this.value)">${teamSession.workspaces.map(w=>`<option value="${w.id}" ${w.id===teamWorkspaceId?'selected':''}>${esc(w.name)} · ${esc(w.role)}</option>`).join('')}</select></label>`:'<p>No workspace yet. The Super Admin can create a fictional hospital and approve staff access.</p>'}${window.fnAccount?.isOwner()?'<button class="btn primary" onclick="openTeamCreate()">Create demo hospital</button>':''}</div>${teamData?`<p>Signed-in operator: <b>${esc(teamData.membership.label)}</b> · server role: <b>${esc(teamData.membership.role)}</b>. ${teamData.membership.role==='admin'?'Administrator rehearsal can perform each handoff. The audit logs your actual admin identity and the workflow role; this is not a test of separate staff accounts.':'The server restricts actions to your assigned role.'}</p><p class="mini">Last server refresh ${fmt(teamData.serverTime)}. Refreshes about every 10 seconds while this screen is visible; stale revisions cannot overwrite newer work. Automatic refresh pauses while you edit a handoff.</p><div class="actions">${teamRoleCan('nurse')?'<button class="btn primary" onclick="openTeamVisit()">New synthetic visit</button>':''}${teamData.membership.role==='admin'?'<button class="btn" onclick="fnAccount.admin()">Manage registration requests</button>':''}<button class="btn" onclick="exportTeamSnapshot()">Export shared demo record</button></div>`:''}</section>${teamData?teamQueueView()+teamDetailView()+teamAuditView():''}`}`}
function chooseTeamWorkspace(id){teamWorkspaceId=id;teamVisitId='';teamData=null;refreshTeamWorkspace()}
function teamQueueView(){return `<section class="panel" style="margin-top:20px"><div class="sectiontitle"><div><h2>Shared visits and role tasks</h2><p>${teamData.visits.length} server visits · ${teamData.visits.filter(v=>v.stage!=='complete').length} outstanding handoffs</p></div></div><div class="scroll"><table><thead><tr><th>Synthetic case</th><th>Next responsibility</th><th>Revision / updated</th><th>Open</th></tr></thead><tbody>${teamData.visits.map(v=>`<tr><td>${esc(v.case_code)}<br><small>Visit ${v.id.slice(0,8)}</small></td><td><span class="pill ${v.stage==='complete'?'':'amber'}">${teamStages[v.stage].label}</span></td><td>v${v.revision} · ${fmt(v.updated_at)}</td><td><button class="btn" onclick="teamVisitId='${v.id}';render()">Open shared visit</button></td></tr>`).join('')||'<tr><td colspan="4">No visits yet. Create a synthetic visit to start the first handoff.</td></tr>'}</tbody></table></div></section>`}
function teamDetailView(){const v=teamData.visits.find(v=>v.id===teamVisitId);if(!v)return '';const s=v.snapshot,m=s.measurements,role=teamStages[v.stage].role;let form='';if(role&&teamRoleCan(role)){const action=v.stage==='physician_review'?'submit_plan':v.stage==='pharmacy_review'?'pharmacy_review':'record_dose';form=`<form onsubmit="event.preventDefault();submitTeamHandoff(this)"><input type="hidden" name="operationKey" value="${teamRequestId()}"><input type="hidden" name="visitId" value="${v.id}"><input type="hidden" name="revision" value="${v.revision}"><input type="hidden" name="action" value="${action}">${action==='submit_plan'?`<label class="field">Reviewable draft plan<textarea name="plan" id="teamDraftPlan" required maxlength="4000" placeholder="Document a synthetic review plan; no orders are transmitted.">${esc(s.plan?.text||(s.a2a&&window.fnA2A?fnA2A.planText(s):''))}</textarea></label><button class="btn" type="button" onclick="loadTeamLocalDraft('${v.case_code}')">Copy current device-local order draft</button>`:action==='pharmacy_review'?'<label class="field">Pharmacy decision<select name="decision"><option value="pharmacy_review">Reviewed for demo nursing handoff</option><option value="request_changes">Request physician changes</option></select></label>':`<div class="grid2"><label class="field">Synthetic regimen documented<input name="regimen" required maxlength="300"></label><label class="field">Actual administration time<input name="administeredAt" type="datetime-local" required></label></div>`}<label class="field">${action==='submit_plan'?'Physician rationale':action==='pharmacy_review'?'Pharmacy findings / safety gaps':'Nursing documentation note'}<textarea name="note" required maxlength="800"></textarea></label><p id="teamFormError" role="alert"></p><button type="submit" class="btn primary">${action==='submit_plan'?'Save plan and request pharmacy review':action==='pharmacy_review'?'Save pharmacy decision':'Record dose and complete demo handoff'}</button></form>`}else if(role)form=`<p>This step requires the <b>${role}</b> role. Your current server role cannot perform it.</p>`;return `<section class="panel" style="margin-top:20px"><h2>${esc(v.case_code)} · shared visit v${v.revision}</h2><div class="compactstats"><span>Age <b>${m.age??'Unknown'}</b></span><span>Temperature <b>${m.temperature??'Unknown'} °C</b></span><span>ANC <b>${m.anc??'Unknown'} ×10⁹/L</b></span><span>SBP <b>${m.systolic??'Unknown'} mmHg</b></span><span>CrCl <b>${m.crcl??'Unknown'} mL/min</b></span></div><p>Triage ${fmt(s.triageAt)} · Source: copied synthetic case plus operator-entered triage time. These values are not live hospital observations.</p><details><summary>Shared plan and pharmacy review</summary><h3>Physician draft</h3><p style="white-space:pre-wrap">${esc(s.plan?.text||'Not submitted')}</p><p>${esc(s.plan?.note||'')}</p><h3>Pharmacy</h3><p>${esc(s.pharmacy?.decision||'Not reviewed')} · ${esc(s.pharmacy?.note||'')}</p></details>${s.dose?`<p><b>Documented synthetic administration:</b> ${esc(s.dose.regimen)} · ${fmt(s.dose.administeredAt)} · ${((Date.parse(s.dose.administeredAt)-Date.parse(s.triageAt))/60000).toFixed(1)} min after triage. This is timing only; appropriateness and clinical response are not automatically validated.</p>`:''}${s.a2a?`<div class="notice"><b>Assessment to action · ${esc(s.a2a.caseId)}</b><p>Saved synthetic structured assessment and proposed items are attached to this visit. Regimen text remains a clinician-editable training draft; no prescription is issued.</p><button class="btn" onclick="fnA2A.openShared('${v.id}')">Open saved assessment</button></div>`:''}<h3>${teamStages[v.stage].label}</h3>${form}${v.stage==='complete'?'<p>First-dose handoff demonstration complete. This does not close the clinical episode, prove treatment effectiveness or authorize discharge.</p>':''}<button class="btn" onclick="openPatient('${v.case_code}')">Open original device-local clinical review</button></section>`}
function teamAuditView(){return `<section class="panel" style="margin-top:20px"><details><summary>Shared audit and team members</summary><h3>Membership</h3>${teamData.members.map(m=>`<p>${esc(m.label)} · ${esc(m.role)}</p>`).join('')}<h3>Server events</h3><div class="scroll"><table><thead><tr><th>Time</th><th>Actor / actual role</th><th>Action / workflow role</th><th>Rationale</th></tr></thead><tbody>${teamData.events.map(e=>`<tr><td>${fmt(e.at)}</td><td>${esc(e.actor_label||'Workspace member')} · ${esc(e.actor_role)}</td><td>${esc(e.action)} · ${esc(e.performed_role)}<br>Visit ${e.visit_id.slice(0,8)}</td><td>${esc(e.note)}</td></tr>`).join('')}</tbody></table></div><p>Server events are append-only through this application API. This prototype does not claim immutable or certified institutional auditing.</p></details></section>`}
function openTeamCreate(){openDialog('Create a fictional hospital',`<form onsubmit="event.preventDefault();createTeamWorkspace(this)"><label class="field">Demo hospital / department name<input name="name" value="FN Training Hospital" required maxlength="100"></label><label class="field">Your operator label<input name="label" required maxlength="100" placeholder="Demo administrator"></label><label><input name="syntheticOnly" type="checkbox" required> Synthetic training data only</label><p id="teamFormError" role="alert"></p><button class="btn primary" type="submit">Create central workspace</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
async function createTeamWorkspace(form){try{const f=Object.fromEntries(new FormData(form)),r=await teamRequest('workspaces','POST',{name:f.name,label:f.label,syntheticOnly:!!f.syntheticOnly});teamWorkspaceId=r.id;closeDialog();await refreshTeamWorkspace()}catch(e){$('#teamFormError').textContent=e.message}}
function openTeamJoin(){openDialog('Join a demo team',`<form onsubmit="event.preventDefault();joinTeamWorkspace(this)"><label class="field">Single-use invitation code<input name="code" required maxlength="100" autocomplete="off"></label><label class="field">Your operator label<input name="label" required maxlength="100"></label><p>The invitation sets your role. You cannot choose a higher role here.</p><p id="teamFormError" role="alert"></p><button class="btn primary" type="submit">Join workspace</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
async function joinTeamWorkspace(form){try{const r=await teamRequest('join','POST',Object.fromEntries(new FormData(form)));teamWorkspaceId=r.id;closeDialog();await refreshTeamWorkspace()}catch(e){$('#teamFormError').textContent=e.message}}
function openTeamInvite(){openDialog('Create a role-specific invitation',`<p>Share the generated code only with an intended test participant. It gives access to this synthetic workspace for the specified role. The code expires after 24 hours and can be used once.</p><form onsubmit="event.preventDefault();createTeamInvite(this)"><label class="field">Role<select name="role"><option value="physician">Physician</option><option value="nurse">Nurse</option><option value="pharmacist">Pharmacist</option></select></label><p id="teamFormError" role="alert"></p><button class="btn primary" type="submit">Generate invitation code</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
async function createTeamInvite(form){try{const r=await teamRequest('invite','POST',Object.fromEntries(new FormData(form)));openDialog('Invitation ready · '+r.role,`<p>Single use · expires ${fmt(r.expiresAt)}. Copy now; the server stores only its hash.</p><label class="field">Invitation code<input readonly value="${esc(r.code)}" onclick="this.select()"></label><p>The recipient signs into the same app, opens Connected demo, then Join by invitation. No email or external message has been sent.</p><button class="btn" onclick="closeDialog()">Close</button>`)}catch(e){$('#teamFormError').textContent=e.message}}
function openTeamVisit(){openDialog('Create shared synthetic visit',`<p>Only the fictional source code and five measurements are copied to the server. Other device-local edits and checklist entries do not automatically synchronize.</p><form onsubmit="event.preventDefault();createTeamVisit(this)"><input type="hidden" name="requestKey" value="${teamRequestId()}"><label class="field">Synthetic source case<select name="caseCode">${patients.map(p=>`<option value="${esc(id(p))}">${esc(id(p))} · ${esc(patientName(p))}</option>`).join('')}</select></label><label class="field">Triage time for this demo visit<input name="triageAt" type="datetime-local" value="${localInput(new Date().toISOString())}" required></label><label><input type="checkbox" name="syntheticOnly" required> I confirm this visit uses fictional training data only</label><p id="teamFormError" role="alert"></p><button class="btn primary" type="submit">Save visit and request physician review</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
async function createTeamVisit(form){try{const f=Object.fromEntries(new FormData(form)),p=patients.find(p=>id(p)===f.caseCode);if(!p)throw Error('Select a source case');const val=k=>typeof p[k]==='number'?p[k]:null;const r=await teamRequest('visits','POST',{caseCode:f.caseCode,requestKey:f.requestKey,syntheticOnly:!!f.syntheticOnly,triageAt:new Date(f.triageAt).toISOString(),measurements:{age:val('Age (years)'),temperature:val('Temp (°C)'),anc:val('ANC (×10⁹/L)'),systolic:val('Systolic BP (mmHg)'),crcl:val('CrCl (mL/min)')}});teamVisitId=r.id;closeDialog();await refreshTeamWorkspace()}catch(e){$('#teamFormError').textContent=e.message}}
function loadTeamLocalDraft(code){const o=state.orderDrafts[code];if(!o){$('#teamFormError').textContent='No device-local draft for this case. Open its clinical review and generate a draft, or type a synthetic plan here.';return}teamEditing=true;$('#teamDraftPlan').value='Device-local draft '+o.subtype+' v'+o.version+' (not signed or transmitted)\n'+o.items.filter(i=>i.include).map(i=>i.text).join('\n')}
async function submitTeamHandoff(form){const btn=form.querySelector('button[type="submit"]');btn.disabled=true;try{const f=Object.fromEntries(new FormData(form));await teamRequest('transition','POST',{id:f.visitId,revision:Number(f.revision),operationKey:f.operationKey,action:f.decision||f.action,note:f.note,plan:f.plan,regimen:f.regimen,administeredAt:f.administeredAt?new Date(f.administeredAt).toISOString():undefined});teamEditing=false;await refreshTeamWorkspace()}catch(e){$('#teamFormError').textContent=e.message;btn.disabled=false}}
function exportTeamSnapshot(){if(teamData)download('FN_SHARED_SYNTHETIC_workspace.json',{syntheticOnly:true,workspace:teamSession.workspaces.find(w=>w.id===teamWorkspaceId),...teamData})}
const renderBeforeTeamWorkspace=render;render=function(){renderBeforeTeamWorkspace();if(view==='Team workspace')$('#app').innerHTML=teamWorkspaceView()};
const goBeforeTeamWorkspace=go;go=function(v){goBeforeTeamWorkspace(v);if(v==='Team workspace'){history.replaceState(null,'','#team');refreshTeamWorkspace()}else if(location.hash==='#team')history.replaceState(null,'',location.pathname+location.search)};
setInterval(()=>{if(view==='Team workspace'&&!document.hidden&&!document.querySelector('#workflowDialog'))refreshTeamWorkspace(true)},10000);
if(location.hash==='#team'){view='Team workspace';refreshTeamWorkspace()}

document.addEventListener('input',e=>{if(view==='Team workspace'&&e.target.closest('#app form'))teamEditing=true});document.addEventListener('change',e=>{if(view==='Team workspace'&&e.target.closest('#app form'))teamEditing=true});
